import {icon} from '../../shared/icons.js';
import {esc,kinds,makeNode,createEditor,outputOf,inputsOf,connect,invalidate,check,orderNodes,canRunNode,timeNow,migrateEditor,macroParams,reportConclusion} from './model.js';
import {renderPreview} from './preview.js';
import {createMolecule,moleculeFormula} from './molecule.js';
import {renderMolecule} from './molecule-preview.js';
import {openMoleculeEditor} from './molecule-editor.js';
import {mountCalculationCanvas} from './infinite-canvas.js';
import {FlowCanvasModel} from './canvas-runtime/canvas-model.js';
const canvasHistories=new Map();

const storageKey=id=>`forge-demo-editor-v1:${id}`;
const cache=new Map(),running=new Map();
export function loadEditor(workflow){if(cache.has(workflow.id))return cache.get(workflow.id);let result;try{const saved=JSON.parse(localStorage.getItem(storageKey(workflow.id))||localStorage.getItem(`forge-editor-v1:${workflow.id}`));if(saved?.workflowId===workflow.id)result=migrateEditor(saved);}catch{}result??=createEditor(workflow);cache.set(workflow.id,result);return result;}
const field=(key,label,value,unit='',type='number')=>`<label class="field"><span>${label}</span><div class="unit-input"><input data-param="${key}" name="${key}" type="${type}" step="any" value="${esc(value)}">${unit?`<small>${unit}</small>`:''}</div></label>`;
const select=(key,label,value,options)=>`<label class="field"><span>${label}</span><select data-param="${key}">${options.map(o=>`<option value="${esc(Array.isArray(o)?o[0]:o)}" ${(Array.isArray(o)?o[0]:o)===value?'selected':''}>${esc(Array.isArray(o)?o[1]:o)}</option>`).join('')}</select></label>`;
const button=(action,text,glyph='',extra='')=>`<button type="button" class="btn" data-editor="${action}" ${extra}>${glyph?icon(glyph):''}${text}</button>`;
export function renderEditor(s){return `<div class="editor-page" data-ui><div class="version-notice"><strong>工作流编辑 V1</strong><span>已保留的工作流交互版本 · 演示数据独立保存</span><button class="text-btn" data-return-editor="/multiscale/workflows/${esc(s.workflowId)}/edit">进入当前物理建模版本</button></div>
  <section class="task-header"><div><button class="editor-back" data-action="back" aria-label="返回工作流列表">${icon('chevron')}</button><div class="editor-title"><div class="title-row"><h1><input data-workflow-name aria-label="工作流名称" value="${esc(s.name)}"></h1><span class="status">${esc(s.definition)}</span></div><small id="editor-save" role="status">已保存在本机（演示）</small></div></div><div class="header-actions">${button('validate','检查依赖','check')}<button class="btn primary" data-editor="run">${icon('play')}运行工作流</button></div></section>
  <div class="editor-run-strip" id="editor-run-strip"></div>
  <main class="workbench">
    <section class="copilot" aria-label="研究 Copilot"><div class="panel-title"><div class="copilot-title"><span class="ai-emblem">${icon('spark')}</span><strong>研究 Copilot</strong><span class="online-dot"></span></div><small>本地演示</small></div><div class="conversation" id="editor-conversation" aria-live="polite"></div><div class="chat-bottom"><div class="editor-context" id="editor-context"></div><form class="copilot-composer" data-editor-form="chat"><label class="sr-only" for="editor-chat">向研究 Copilot 提问</label><textarea id="editor-chat" placeholder="描述你的想法，或让 AI 协助修改…" rows="2">${esc(s.draft||'')}</textarea><div class="composer-footer"><span class="composer-context">${icon('flow')}当前工作流上下文</span><button class="send-btn" aria-label="发送消息">${icon('arrow')}</button></div></form></div></section>
    <div class="right-workspace">
      <section class="flow-panel dependency-panel">
        <div class="section-heading"><h2>计算依赖图 <span id="editor-count"></span></h2>${button('add','添加计算节点','plus')}</div>
        <div class="graph-description">微观模拟 → 宏观建模 → 计算调度 → 结果呈现</div>
        <div class="dependency-canvas rf-main task-canvas-surface editor-infinite-surface" id="editor-infinite" aria-label="计算工作流无限画布"></div>
        <div class="pipeline-footer"><span>连线表示参数依赖 · 拖动卡片调整位置</span><div class="graph-tools">${button('connect','连接映射')}${button('zoom-out','−')}<span id="editor-zoom">100%</span>${button('zoom-in','＋')}${button('fit','适配')}</div></div>
      </section>
      <section class="detail-panel" id="editor-detail" aria-label="节点模型与配置"></section>
      <footer class="workspace-footer"><span>SynMatAI · 计算工作流</span><span>原型演示 · 模型与数值均为示意</span></footer>
    </div>
  </main></div>`;}

export function mountEditor(root,s,{notify,navigate,openDialog,onUpdate}){
  const q=selector=>root.querySelector(selector);let cleanupPreview=()=>{},timer=running.get(s.workflowId)||null,disposed=false;
  const node=id=>s.nodes.find(n=>n.id===id);const selected=()=>node(s.selected);let issues=null,canvasView=null;
  const canvasHistory=canvasHistories.get(s.workflowId)||{undo:[],redo:[]};canvasHistories.set(s.workflowId,canvasHistory);
  const definitionSnapshot=()=>structuredClone({nodes:s.nodes,edges:s.edges,revision:s.revision,definition:s.definition,selected:s.selected,embeddedCanvasPositions:s.embeddedCanvasPositions});
  function remember(){canvasHistory.undo.push(definitionSnapshot());canvasHistory.redo=[];}
  function undoCanvas(redo=false){const from=redo?canvasHistory.redo:canvasHistory.undo,to=redo?canvasHistory.undo:canvasHistory.redo;if(!from.length)return;to.push(definitionSnapshot());const previous=from.pop(),currentRevision=s.revision;Object.assign(s,previous);s.revision=Math.max(currentRevision,previous.revision)+1;s.checkedRevision=null;record(redo?'重做画布修改':'撤销画布修改');refresh();}
  function selectCanvasNode(id,open=false){if(!node(id))return;s.selected=id;s.tab='model';save();renderDetail();renderChat();if(open)q('#editor-detail').scrollIntoView({behavior:'smooth',block:'nearest'});}
  function addCanvasContext(ids){s.contextReferences=[...new Set([...(s.contextReferences||[]),...ids])].filter(id=>node(id));save();renderChat();q('#editor-chat').focus();notify('已将选中节点引用到 Copilot');}
  function createCanvasNode(type,point,before=[],fromSide='right',exact=false){if(!kinds[type])return;remember();const n=makeNode(type,`node-${Date.now()}`);const positions=s.embeddedCanvasPositions||{};const sizes=Object.fromEntries(Object.keys(positions).map(id=>[id,{width:196,height:126}]));const preferred=FlowCanvasModel.newNodePosition(before,[],positions,sizes,{width:196,height:126},point,exact);n.x=preferred.x;n.y=preferred.y;s.nodes.push(n);s.embeddedCanvasPositions??={};s.embeddedCanvasPositions[n.id]=preferred;let message='已创建 '+n.name;for(const id of before){const error=connect(s,id,n.id,inputsOf(n)[0]?.[0]);if(!error){const edge=s.edges.find(e=>e.from===id&&e.to===n.id);edge.fromPort=fromSide||'right';edge.toPort='left';}else message+='；'+error;}s.revision++;s.checkedRevision=null;s.definition='草稿';s.selected=n.id;record('新增计算节点 '+n.name);refresh();canvasView?.controller.selectNode(n.id);notify(message);}
  function removeCanvasNodes(ids){const nodes=ids.map(node).filter(Boolean);if(!nodes.length)return;const affected=s.edges.filter(e=>ids.includes(e.from)||ids.includes(e.to));const d=openDialog(`<div class="dialog-form"><h2>删除所选节点</h2><p>将删除 ${nodes.length} 个节点及 ${affected.length} 条连接，历史执行记录保留。可使用撤销恢复。</p><p>${nodes.map(n=>esc(n.name)).join('、')}</p><div class="dialog-actions"><button class="btn" data-dialog-close>取消</button><button class="btn primary" data-confirm-canvas-delete>确认删除</button></div></div>`);d.querySelector('[data-confirm-canvas-delete]').onclick=()=>{remember();ids.forEach(id=>invalidate(s,id));s.nodes=s.nodes.filter(n=>!ids.includes(n.id));s.edges=s.edges.filter(e=>!ids.includes(e.from)&&!ids.includes(e.to));s.selected=s.nodes[0]?.id||null;s.inspectorOpen=false;s.contextReferences=(s.contextReferences||[]).filter(id=>node(id));record('删除画布节点 '+nodes.map(n=>n.name).join('、'));d.close();refresh();};}
  function deleteCanvasEdge(edge){if(!edge)return;const d=openDialog(`<div class="dialog-form"><h2>删除连线</h2><p>${esc(node(edge.from).name)} → ${esc(node(edge.to).name)}</p><p>${esc(edge.output)} → ${esc(edge.input)} · ${esc(edge.unit)}</p><p>可撤销恢复，历史执行快照保留。</p><div class="dialog-actions"><button class="btn" data-dialog-close>取消</button><button class="btn primary" data-confirm-canvas-edge>确认删除连线</button></div></div>`);d.querySelector('[data-confirm-canvas-edge]').onclick=()=>{remember();s.edges=s.edges.filter(e=>e.id!==edge.id);change(edge.to,'删除输入映射 '+edge.input);d.close();};}
  function connectCanvasNodes(from,to,fromPort,toPort){const target=node(to),source=node(from);if(!target||!source)return;if(s.edges.some(e=>e.from===from&&e.to===to))return notify('这两个节点之间已存在连线，可通过连线操作编辑映射');const old=definitionSnapshot(),error=connect(s,from,to,inputsOf(target)[0]?.[0]);if(error)return notify(error);canvasHistory.undo.push(old);canvasHistory.redo=[];const edge=s.edges.find(e=>e.from===from&&e.to===to);edge.fromPort=fromPort;edge.toPort=toPort;s.selected=to;record('连接 '+kinds[source.type]+' → '+kinds[target.type]);refresh();}

  function save(){
    const label=q('#editor-save');if(label)label.textContent='保存中…';
    try{localStorage.setItem(storageKey(s.workflowId),JSON.stringify(s));if(label)label.textContent='已保存在本机（演示）';onUpdate(s);}
    catch{if(label)label.innerHTML='保存失败 <button data-editor="retry-save">重试</button>';}
  }
  function record(text,id=s.selected){s.history.unshift({id,text,time:timeNow()});save();}
  function refresh(){if(disposed)return;renderHeader();renderRun();syncStageHeight();renderGraph();renderDetail();renderChat();}
  function renderHeader(){q('.status').textContent=s.definition;q('[data-editor="run"]').disabled=!!timer;q('#editor-infinite').dataset.busy=String(!!timer);}
  function pick(id){selectCanvasNode(id,true);canvasView?.controller.selectNode(id);canvasView?.controller.focus(id);}
  function renderGraph(){
    const agent=q('.copilot'),main=q('#editor-infinite');canvasView?.destroy();
    q('#editor-count').textContent=s.nodes.length+' 个工作流节点';
    canvasView=mountCalculationCanvas(main,agent,s,{
      canUndo:()=>canvasHistory.undo.length>0,canRedo:()=>canvasHistory.redo.length>0,undo:undoCanvas,
      select:selectCanvasNode,context:addCanvasContext,create:createCanvasNode,remove:removeCanvasNodes,
      connect:connectCanvasNodes,editEdge:edge=>connectDialog(edge),deleteEdge:deleteCanvasEdge,
      info:notify,view:camera=>{q('#editor-zoom').textContent=Math.round(camera.zoom*100)+'%';},
    });
    requestAnimationFrame(()=>{if(!disposed)syncStageHeight();});
  }
  function syncStageHeight(){canvasView?.controller.refreshLayout();}
  function paramsFor(n){
    const p=n.params,g=s.group;
    if(n.type==='macro')return select('case','模型案例',p.case,[['generic','通用宏观模型'],['tim','颗粒填充 TIM（案例）'],['flow','简单圆管流动（案例）']])+field('modelName','模型名称',p.modelName,'','text')+paramsFor({...n,type:p.case});
    if(n.type==='generic')return '<h3>通用宏观模型</h3>'+field('description','模型说明',p.description,'','text')+'<p class="binding-note">几何、网格、材料与边界属于宏观模型内部配置；具体物理模型与算法接口待接入。</p>';
    if(n.type==='schedule')return '<h3>计算调度</h3>'+select('strategy','调度策略',p.strategy,['按依赖执行'])+select('resource','计算资源',p.resource,['本地演示'])+field('cores','并行核数',p.cores)+field('retries','失败重试次数',p.retries)+'<p class="binding-note">接收宏观模型，按依赖提交计算并向结果呈现传递输出。当前为本地原型演示。</p>';
    if(n.type==='micro')return `<h3>微观模拟配置</h3><p class="binding-note">当前分子：${esc((p.molecule||createMolecule()).name)} · ${esc(moleculeFormula(p.molecule||createMolecule()))}</p>${select('task','已有任务',p.task,[['md-epoxy-021','环氧基体热导率 · md-epoxy-021'],['md-silicone-008','硅氧烷热导率 · md-silicone-008'],['','未选择任务']])}<div class="node-state-message">来源 v1 · 采样温度 300 K<br>已有热导率标量：0.24 W/(m·K)<br>${p.moleculeSource==='local-draft'?'当前分子已修改，原结果不代表新结构的计算结果。':'预览为本地分子示例，尚未关联真实任务的结构文件。'}</div>${button('existing','打开已有微观模拟','flask')}${button('upstream-wait','演示：上游未完成')}${button('upstream-ready','恢复已有结果')}`;
    if(n.type==='result')return `<h3>结果呈现</h3>${select('format','报告格式',p.format,['PDF'])}${select('presentation','呈现方式',p.presentation,['报告与文本结论'])}<div class="node-state-message">求解状态：${esc(s.runs.at(-1)?.status||'尚未运行')}<br>报告状态：${esc(s.runs.at(-1)?.reportStatus||'等待上游结果')}</div>${button('results','查看作业与结果','file')}${button('report-fail','演示：报告生成失败')}${button('report-retry','重试生成报告')}`;
    if(n.type==='flow')return `<h3>简单圆管流动</h3>${field('length','圆管长度',p.length,'mm')}${field('diameter','内径',p.diameter,'mm')}${field('density','密度',p.density,'kg/m³')}${field('temperature','生产温度',p.temperature,'K')}${field('consistency','稠度系数（示例）',p.consistency,'Pa·sⁿ')}${field('exponent','幂律指数（示例）',p.exponent)}<p class="binding-note">引用已有广义牛顿模型；具体支持清单待算法接口确认。</p>${field('inlet','入口速度',p.inlet,'m/s')}${field('outlet','出口表压',p.outlet,'Pa')}<p class="binding-note">壁面：无滑移 · 出口面 ${p.outlet===''?'未绑定':'outlet-1'}</p>`;
    if(g==='geometry'){
      const a=p;
      return `<h3>几何设置</h3><p class="binding-note">长方体基体 · 非接触颗粒预设</p>${field('length','长度',a.length,'mm')}${field('width','宽度',a.width,'mm')}${field('height','厚度',a.height,'mm')}${select('particle','颗粒预设',a.particle,['球形'])}${select('distribution','填充分布',a.distribution,['均一','随机'])}${field('seed','随机种子',a.seed)}${field('target','目标填充率（待确认输入）',a.target,'%')}${field('gap','最小间隙',a.gap,'mm')}<p class="binding-note">实际填充率来自生成结果，不能用目标值替代。</p>`;
    }
    if(g==='mesh')return `<h3>网格设置</h3>${field('mesh','网格尺寸',p.mesh||.2,'mm')}<p class="binding-note">几何检查通过后生成网格。工具及文件格式待算法契约确认。</p>${button('geometry-check','检查几何','check')}`;
    if(g==='materials')return `<h3>材料与界面</h3>${select('source','基体热导率来源',p.source,['引用上游','手工输入'])}${field('matrix','基体热导率',p.matrix,'W/(m·K)')}${field('filler','填料热导率',p.filler,'W/(m·K)')}${field('resistance','界面热阻',p.resistance,'m²·K/W')}<p class="binding-note">微观数据的物性映射在当前宏观模型内配置；手工值需由用户确认。</p>${button('missing','演示：缺少填料热导率')}`;
    if(g==='boundary')return `<h3>边界条件</h3>${select('direction','计算方向',p.direction,['X','Y','Z'])}${field('hot','热端温度',p.hot,'°C')}${field('cold','冷端温度',p.cold,'°C')}<label class="field"><span>侧面边界</span><input value="绝热（固定）" readonly></label>`;
    return '<h3>求解设置</h3><div class="node-state-message">执行：四阶段工作流本地演示<br>三维 · 稳态 · 纯导热<br>不包含其他物理场。</div>';
  }
  function mappingTable(n){const incoming=s.edges.filter(e=>e.to===n.id);return `<details class="editor-mapping" ><summary>输入映射与来源 <span>${incoming.length} 项连接</span></summary><div class="bindings"><p class="binding-note">阶段连线和来源版本随执行快照保留；具体物性字段与单位在宏观模型内配置。</p><table class="binding-table"><thead><tr><th>上游输出 → 目标输入</th><th>阶段规则</th><th>来源</th><th>操作</th></tr></thead><tbody>${incoming.map(e=>`<tr><td>${esc(node(e.from)?.name)}<small>${esc(e.output)} → ${esc(e.input)}</small></td><td>相邻阶段正向连接</td><td>v${node(e.from)?.version} · ${esc(node(e.from)?.status)}<small>${esc(s.runs.at(-1)?.id||'当前定义')}</small></td><td><button class="text-btn" data-editor="disconnect" data-id="${e.id}">断开</button></td></tr>`).join('')||'<tr><td colspan="4">无输入映射；可通过“连接映射”选择已有输出。</td></tr>'}</tbody></table>${button('connect','连接上游输出','plus')}</div></details>`;}
  function editMolecule(n){openMoleculeEditor(openDialog,n.params.molecule||createMolecule(),next=>{if(JSON.stringify(next)===JSON.stringify(n.params.molecule||createMolecule()))return notify('分子结构未发生变化');remember();n.params.molecule=next;n.params.moleculeSource='local-draft';change(n.id,'修改分子结构：'+next.name+'；下游结果需更新');notify('分子结构已应用，请重新检查并运行工作流');});}
  function renderDetail(){
    cleanupPreview();const panel=q('#editor-detail'),n=selected();if(!n){panel.innerHTML='<div class="empty-state">选择节点查看模型与配置，或添加第一个计算节点。</div>';return;}
    const hist=s.history.filter(h=>h.id===n.id);
    panel.innerHTML=`<div class="detail-heading"><div><span class="node-tag">${kinds[n.type]}</span><h2>${esc(n.name)}</h2><span class="node-description">${esc(outputOf(n)[1])} · 定义 v${n.version} · 原型演示</span></div><div class="detail-actions"><span class="ready-label">${esc(n.status)}</span>${button('run-node','运行此节点','play',canRunNode(s,n)&&!timer?'':'disabled title="需检查通过且上游输出有效"')}${n.type==='macro'&&n.params.case==='tim'?button('ai-edit','AI 辅助修改','spark'):''}${button('delete','删除节点')}</div></div><div class="detail-tabs" role="tablist" aria-label="节点内容"><button role="tab" aria-selected="${s.tab==='model'}" class="${s.tab==='model'?'selected':''}" data-editor-tab="model">模型与配置</button><button role="tab" aria-selected="${s.tab==='history'}" class="${s.tab==='history'?'selected':''}" data-editor-tab="history">变更记录 <span>${hist.length}</span></button></div><div id="editor-detail-body"></div>`;
    const body=q('#editor-detail-body');
    if(s.tab==='history'){body.innerHTML=`<div class="history-list">${hist.map(h=>`<div class="history-row"><time>${esc(h.time)}</time><span>${esc(h.text)}</span></div>`).join('')||'<p>暂无变更记录</p>'}</div>`;return;}
    const model=n.type==='macro'&&['tim','flow'].includes(n.params.case),report=n.type==='result',micro=n.type==='micro';
    body.innerHTML=`${model?`<div class="editor-settings">${[['geometry','几何'],['mesh','网格'],['materials','材料与界面'],['boundary','边界条件'],['solver','求解设置']].map(([id,label])=>`<button class="${s.group===id?'selected':''}" data-group="${id}">${label}</button>`).join('')}</div>`:''}<div class="thermal-layout"><div class="thermal-preview"><div class="preview-meta">${micro?'分子结构预览 · 本地原型示例':model?(n.params.case==='flow'?'简单圆管流道 / 入口与出口':'TIM 基体 / 离散非接触颗粒'):report?'报告与仿真结论':'节点内容与配置'}</div>${micro?'<div id="editor-molecule-preview"></div>':model?'<div id="editor-preview"></div>':report?renderReport(s):`<div class="editor-info-visual">${icon(n.type==='micro'?'molecule':'flow')}<strong>${esc(n.name)}</strong><span>${esc(outputOf(n)[1])}</span><div class="property-output">${n.type==='micro'?'引用已有微观任务及其结构化输出':n.type==='schedule'?'依赖调度 · 资源配置 · 执行输出':'模型定义 · 输入映射 · 案例配置'}<br>原型演示</div></div>`}</div><form class="thermal-properties" data-editor-form="params">${paramsFor(n)}${button('save-params','保存参数','check')}<div class="editor-save-hint">修改后，下游旧结果保留并标记过期</div></form></div>${mappingTable(n)}<details class="editor-validation" ${issues?'open':''}><summary>依赖与算法校验 <span>${issues?issues.length+' 项问题':'尚未检查当前修改'}</span></summary><div class="editor-validation-body">${issues?issues.length?issues.map(i=>`<button data-select-node="${i.nodeId||''}"><strong>${esc(i.name)} · ${esc(i.field)}</strong><span>${esc(i.reason)} → 定位</span></button>`).join(''):'<p class="check-success">当前依赖与演示参数检查通过。</p>':'<p>运行前检查输入完整性、单位和几何预设。</p>'}${button('validate','检查依赖','check')}</div></details>`;
    if(micro){const viewer=renderMolecule(q('#editor-molecule-preview'),n.params.molecule||createMolecule(),{onEdit:()=>editMolecule(n)});cleanupPreview=()=>viewer.destroy();}
    if(model)cleanupPreview=renderPreview(q('#editor-preview'),n.params,{flow:n.params.case==='flow',highlight:s.group});
  }
  function renderReport(state){const r=state.runs.at(-1),ready=r?.status==='成功'&&r.reportStatus==='已生成';return `<div class="editor-report"><div class="report-file">${icon('file')}<strong>${ready?'仿真结果报告.pdf':'等待上游结果'}</strong><span>${esc(r?.id||'尚未运行')} · 原型演示</span></div>${ready?`<h3>本次仿真结论</h3><p>${reportConclusion(r)}</p>${button('preview-report','预览报告','file')}${button('download-report','下载报告','download')}${button('copy-conclusion','复制结论','copy')}`:`<p>求解与报告状态分别维护。报告生成完成后显示文件和文本结论。</p>`}</div>`;}
  function renderChat(){
    const n=selected();q('#editor-context').innerHTML=(n?`当前节点：${esc(n.name)}`:'工作流上下文')+(s.contextReferences?.length?`<div class="canvas-context-chips">${s.contextReferences.filter(id=>node(id)).map(id=>`<button type="button" data-remove-reference="${esc(id)}" title="移除引用">${esc(node(id).name)} ×</button>`).join('')}</div>`:'');
    q('#editor-conversation').innerHTML=`<div class="chat-date">本次模拟会话 · 原型演示</div><div class="assistant-message"><div class="agent-label">${icon('spark')}SynMatAI</div><p>工作流按微观模拟、宏观建模、计算调度、结果呈现四阶段组织。几何、网格和材料等配置属于宏观模型内部。</p><div class="chat-checks"><span><i>✓</i>历史执行快照独立保留</span><span><i>✓</i>参数来源与单位可追溯</span><span><i class="pending">!</i>修改输入后需要重新检查</span></div><button class="suggestion-card" data-select-node="${s.nodes.find(n=>n.type==='macro')?.id||''}"><span>${icon('flask')}<strong>查看宏观输入依赖</strong></span><small>定位宏观模型与微观数据映射</small><span class="suggestion-link">定位宏观计算节点 ${icon('chevron')}</span></button></div>${s.messages.map(m=>`<div class="${m.user?'user-message':'assistant-message'}">${esc(m.text)}</div>`).join('')}`;
  }
  function renderRun(){const r=s.runs.at(-1);q('#editor-run-strip').innerHTML=r?`<div class="run-summary"><span class="run-state">${r.status==='成功'?icon('check'):icon('flow')}<strong>${esc(r.status)}${r.status==='运行中'?' · 演示执行':''}</strong></span><span>${esc(r.id)} · 报告${esc(r.reportStatus)}</span><div class="editor-progress"><span style="width:${r.progress}%"></span></div>${button('results','查看本次作业')}${timer?button('cancel','取消执行'):''}</div>`:'';}
  function change(id,text){invalidate(s,id);node(id).version++;issues=null;record(text,id);refresh();}
  function commitParams(){const n=selected();if(!n)return;remember();const inputs=[...q('[data-editor-form="params"]').querySelectorAll('[data-param]')];let changed=new Set();for(const input of inputs){const target=n;if(!target)continue;const value=input.type==='number'?(input.value===''?'':Number(input.value)):input.value;if(target.params[input.dataset.param]!==value){target.params[input.dataset.param]=value;changed.add(target.id);}}for(const id of changed)change(id,'保存节点参数，相关下游结果已过期');if(!changed.size)notify('参数未发生变化');else notify('已保存参数，请检查依赖后重新执行');}
  function validate(){issues=check(s);s.checkedRevision=issues.length?null:s.revision;if(!issues.length)s.definition='可运行';else s.definition='草稿';record(`检查依赖：${issues.length?issues.length+' 项问题':'检查通过'}`);refresh();notify(issues.length?`发现 ${issues.length} 项问题，可在配置下方定位`:'依赖与演示参数检查通过');}
  function run(onlySelected=false){
    if(timer)return;const problems=check(s);if(problems.length){issues=problems;refresh();notify('输入或依赖未通过检查，无法执行');return;}
    if(s.checkedRevision!==s.revision){validate();notify('当前修改已检查通过，请再次运行');return;}
    if(onlySelected&&!canRunNode(s,selected()))return notify('需要先生成有效上游输出');
    let ordered;try{ordered=onlySelected?[selected()]:orderNodes(s);}catch(e){return notify(e.message);}
    const snapshot=JSON.parse(JSON.stringify({nodes:s.nodes,edges:s.edges,revision:s.revision}));
    const r={id:`run-demo-${Date.now()}`,status:'运行中',time:timeNow(),progress:0,reportStatus:'等待上游',snapshot,solver:'原型调度演示',demo:true,logs:['已固化输入快照；原型演示，不执行真实科学计算。']};s.runs.push(r);let index=0;
    timer=setInterval(()=>{if(r.status==='已取消'){clearInterval(timer);running.delete(s.workflowId);timer=null;return;}if(index<ordered.length){const n=node(ordered[index].id);if(n){if(s.revision===snapshot.revision)n.status='成功';r.logs.push(`${n.name}：演示完成`);}index++;if(ordered[index]&&s.revision===snapshot.revision)node(ordered[index].id).status='运行中';r.progress=Math.round(index/ordered.length*90);if(index===ordered.length){r.reportStatus=ordered.some(n=>n.type==='result')?'生成中':'等待上游';}save();refresh();}else{clearInterval(timer);running.delete(s.workflowId);timer=null;r.status='成功';r.progress=100;r.reportStatus=ordered.some(n=>n.type==='result')?'已生成':'等待上游';if(s.revision===snapshot.revision)s.definition='可运行';record('演示执行结束，快照及报告状态已保存');refresh();notify('演示执行完成');}document.dispatchEvent(new CustomEvent('forge:run-progress',{detail:s.workflowId}));},650);
    running.set(s.workflowId,timer);
    if(ordered[0])ordered[0].status='运行中';record('创建独立执行快照 '+r.id);refresh();
  }
  function connectDialog(edge){const n=selected();const content=`<form class="dialog-form" data-local-form="connect"><div class="dialog-copy"><h2>连接映射</h2><p>仅支持微观模拟 → 宏观建模 → 计算调度 → 结果呈现，相邻阶段正向连接。</p></div><label class="form-field"><span>上游节点</span><select name="from">${s.nodes.map(a=>`<option value="${a.id}" ${a.id===edge?.from?'selected':''}>${esc(a.name)} · ${outputOf(a)[2]}</option>`).join('')}</select></label><label class="form-field"><span>目标输入</span><select name="target">${s.nodes.flatMap(a=>inputsOf(a).map(p=>`<option value="${a.id}|${p[0]}" ${(edge?edge.to===a.id&&edge.input===p[0]:n?.id===a.id)?'selected':''}>${esc(a.name)} / ${p[1]} · ${p[2]}</option>`)).join('')}</select></label><p class="editor-form-error" role="alert"></p><div class="dialog-actions"><button class="btn" type="button" data-dialog-close>取消</button><button class="btn primary">确认映射</button></div></form>`;const d=openDialog(content);d.querySelector('form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);if(!f.get('target')){d.querySelector('.editor-form-error').textContent='请先添加具有输入端口的节点';return;}const [to,input]=f.get('target').split('|');const before=definitionSnapshot();const err=connect(s,f.get('from'),to,input);if(err){d.querySelector('.editor-form-error').textContent=err;return;}canvasHistory.undo.push(before);canvasHistory.redo=[];record('更新数据映射：'+input,to);d.close();refresh();};}
  function aiDialog(){const n=selected();if(!n)return;const old=n.params.seed??42;const d=openDialog(`<div class="dialog-form"><div class="dialog-copy"><h2>AI 辅助修改 · 演示</h2><p>仅展示用户确认流程，不自动生成物性或代替算法校验。</p></div><div class="ai-diff"><strong>几何随机种子</strong><dl><dt>修改前 → 修改后</dt><dd>${old} → ${Number(old)+1}</dd></dl><p>改变颗粒排布示意，相关下游输出将过期。</p></div><div class="dialog-actions"><button class="btn" data-dialog-close>取消</button><button class="btn primary" data-apply-ai>确认并应用</button></div></div>`);d.querySelector('[data-apply-ai]').onclick=()=>{const g=n;if(!g)return notify('请先选择 TIM 宏观模型案例');g.params.seed=Number(old)+1;g.params.distribution='随机';change(g.id,`应用 AI 演示修改：随机种子 ${old} → ${g.params.seed}`);d.close();};}
  function reportText(){const r=s.runs.at(-1);return `SynMatAI 仿真结果报告（原型演示）\n执行：${r?.id}\n执行：四阶段工作流本地演示\n${reportConclusion(r)}`;}
  function showResults(){const r=s.runs.at(-1);if(!r)return notify('尚无执行记录');save();navigate(`/multiscale/runs?workflowId=${s.workflowId}&runId=${r.id}&nodeId=${s.selected||''}`);}
  root.addEventListener('click',onClick);root.addEventListener('change',onChange);root.addEventListener('submit',onSubmit);root.addEventListener('input',onInput);root.addEventListener('keydown',onKey);
  function onClick(e){
    const pickButton=e.target.closest('[data-select-node]');if(pickButton){if(pickButton.dataset.wasDragged){delete pickButton.dataset.wasDragged;return;}if(node(pickButton.dataset.selectNode))pick(pickButton.dataset.selectNode);return;}
    const group=e.target.closest('[data-group]');if(group){s.group=group.dataset.group;save();renderDetail();return;}
    const tab=e.target.closest('[data-editor-tab]');if(tab){s.tab=tab.dataset.editorTab;save();renderDetail();return;}
    const edge=e.target.closest('[data-edge]');if(edge){connectDialog(s.edges.find(a=>a.id===edge.dataset.edge));return;}
    const ref=e.target.closest('[data-remove-reference]');if(ref){s.contextReferences=s.contextReferences.filter(id=>id!==ref.dataset.removeReference);save();renderChat();return;}
    const action=e.target.closest('[data-editor]')?.dataset.editor;if(!action)return;
    if(action==='zoom-in')canvasView?.controller.zoomIn();if(action==='zoom-out')canvasView?.controller.zoomOut();if(action==='fit')canvasView?.controller.fit();
    if(action==='validate')validate();if(action==='run')run();if(action==='run-node')run(true);if(action==='add')canvasView?.controller.openCreateMenu();if(action==='delete')removeCanvasNodes([s.selected]);if(action==='connect')connectDialog();if(action==='save-params')commitParams();if(action==='ai-edit')aiDialog();if(action==='retry-save')save();
    if(action==='report-fail'||action==='report-retry'){const r=s.runs.at(-1);if(r?.status!=='成功')return notify('请先完成求解演示');r.reportStatus=action==='report-fail'?'失败':'已生成';selected().status=action==='report-fail'?'失败':'成功';record(action==='report-fail'?'报告生成失败（演示）；求解成功状态保留':'重新生成演示报告');refresh();}if(action==='results')showResults();if(action==='existing')notify('打开系统已有微观模拟（原型入口）');
    if(action==='disconnect'){const id=e.target.closest('[data-id]').dataset.id,edge=s.edges.find(a=>a.id===id);if(edge){remember();s.edges=s.edges.filter(a=>a.id!==id);change(edge.to,'断开输入映射 '+edge.input);}}
    if(action==='missing'){selected().params.filler='';change(selected().id,'清空填料热导率（演示）');}
    if(action==='upstream-wait'){invalidate(s,selected().id);selected().status='等待上游';record('已有微观任务尚未完成（演示）');refresh();}
    if(action==='upstream-ready'){selected().status='成功';record('恢复已有微观结果（演示）');refresh();}
    if(action==='geometry-check'){const found=check(s).filter(i=>node(i.nodeId)?.type==='macro');notify(found.length?found[0].reason:'几何预设检查通过：颗粒保留间隙（演示）');}
    if(action==='cancel'){clearInterval(timer);running.delete(s.workflowId);timer=null;const r=s.runs.at(-1);r.status='已取消';r.reportStatus='等待上游';s.nodes.filter(n=>n.status==='运行中').forEach(n=>n.status='已取消');record('取消本次演示执行，配置与快照保留');refresh();}
    if(action==='fit')canvasView?.controller.fit();
    if(action==='preview-report')openDialog(`<div class="dialog-form"><h2>仿真结果报告 · 演示</h2><p class="report-preview">${esc(reportText()).replaceAll('\n','<br>')}</p><div class="dialog-actions"><button class="btn" data-dialog-close>关闭</button></div></div>`);
    if(action==='download-report'){downloadReportPdf(reportText(),s.runs.at(-1).id);}
    if(action==='copy-conclusion')navigator.clipboard.writeText(reportText()).then(()=>notify('仿真结论已复制')).catch(()=>notify('请打开报告手动复制结论'));
  }
  function onInput(e){if(e.target.id==='editor-chat'){s.draft=e.target.value;save();}}
  function onChange(e){if(e.target.matches('[data-param="case"]')){const n=selected();if(n?.type==='macro'){remember();n.caseConfigurations??={};n.caseConfigurations[n.params.case]=structuredClone(n.params);n.params=structuredClone(n.caseConfigurations[e.target.value]||macroParams(e.target.value));s.group='geometry';change(n.id,'切换宏观模型案例；节点类型仍为宏观建模');}return;}if(e.target.matches('[data-workflow-name]')){if(!e.target.value.trim()){e.target.value=s.name;return notify('工作流名称不能为空');}s.name=e.target.value.trim();record('重命名工作流');}}
  function onSubmit(e){if(!e.target.matches('[data-editor-form]'))return;e.preventDefault();if(e.target.dataset.editorForm==='params')commitParams();else{const input=q('#editor-chat'),text=input.value.trim();if(!text)return;s.messages.push({user:true,text},{text:`当前节点：${selected()?.name||'未选择'}。${/修改|优化/.test(text)?'可使用右侧“AI 辅助修改”预览差异并确认应用。':'请在右侧查看输入映射与来源，使用“检查依赖”验证配置。'}本回复为本地演示，不生成未知物性。`});s.draft='';input.value='';save();renderChat();q('#editor-conversation').scrollTop=q('#editor-conversation').scrollHeight;}}
  function onKey(e){if(e.target.matches('[data-edge]')&&(e.key==='Enter'||e.key===' ')){e.preventDefault();connectDialog(s.edges.find(a=>a.id===e.target.dataset.edge));}}
  const progress=e=>{if(e.detail===s.workflowId){timer=running.get(s.workflowId)||null;refresh();}};document.addEventListener('forge:run-progress',progress);
  save();refresh();
  const sizeObserver=new ResizeObserver(syncStageHeight);sizeObserver.observe(q('.task-header'));sizeObserver.observe(q('#editor-run-strip'));window.addEventListener('resize',syncStageHeight);
  return ()=>{disposed=true;canvasView?.destroy();sizeObserver.disconnect();window.removeEventListener('resize',syncStageHeight);cleanupPreview();document.removeEventListener('forge:run-progress',progress);root.removeEventListener('click',onClick);root.removeEventListener('change',onChange);root.removeEventListener('submit',onSubmit);root.removeEventListener('input',onInput);root.removeEventListener('keydown',onKey);};
}

// A small valid PDF containing the demonstration report as a Unicode raster page.
function downloadReportPdf(text,id){
  const c=document.createElement('canvas');c.width=1240;c.height=1754;const ctx=c.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,c.width,c.height);ctx.fillStyle='#243044';ctx.font='28px "Microsoft YaHei", sans-serif';let y=110;for(const line of text.split('\n')){let row='';for(const ch of line){if(ctx.measureText(row+ch).width>1040){ctx.fillText(row,100,y);y+=50;row='';}row+=ch;}ctx.fillText(row,100,y);y+=65;}const image=Uint8Array.from(atob(c.toDataURL('image/jpeg',.9).split(',')[1]),ch=>ch.charCodeAt(0));const enc=new TextEncoder(),parts=[],offsets=[0];let offset=0;const push=t=>{const bytes=typeof t==='string'?enc.encode(t):t;parts.push(bytes);offset+=bytes.length;};push('%PDF-1.4\n');const object=(num,body)=>{offsets[num]=offset;push(`${num} 0 obj\n${body}\nendobj\n`);};object(1,'<< /Type /Catalog /Pages 2 0 R >>');object(2,'<< /Type /Pages /Kids [3 0 R] /Count 1 >>');object(3,'<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /XObject << /Im0 4 0 R >> >> /Contents 5 0 R >>');offsets[4]=offset;push(`4 0 obj\n<< /Type /XObject /Subtype /Image /Width 1240 /Height 1754 /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${image.length} >>\nstream\n`);push(image);push('\nendstream\nendobj\n');const commands='q 595 0 0 842 0 0 cm /Im0 Do Q';object(5,`<< /Length ${commands.length} >>\nstream\n${commands}\nendstream`);const xref=offset;push('xref\n0 6\n0000000000 65535 f \n');for(let i=1;i<=5;i++)push(`${String(offsets[i]).padStart(10,'0')} 00000 n \n`);push(`trailer\n<< /Size 6 /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF`);const url=URL.createObjectURL(new Blob(parts,{type:'application/pdf'})),a=document.createElement('a');a.href=url;a.download=`${id}-仿真结果报告-原型演示.pdf`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
}
